namespace Typhon.Stdlib
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Linq;
    using System.Threading.Tasks;
    using Typhon.Runtime;

    /// <summary>
    /// asyncio on .NET tasks. A coroutine is a Task that is already running (no event loop to schedule it on), so
    /// create_task returns it, and gather/wait_for/as_completed combine tasks.
    /// </summary>
    internal static class asyncio_
    {
        /// <summary>asyncio.TimeoutError (TimeoutError since Python 3.11).</summary>
        internal class TimeoutError : System.TimeoutException { public TimeoutError() : base("") { } }
        internal class CancelledError : OperationCanceledException { public CancelledError() : base("") { } }
        internal class QueueEmpty : Exception { public QueueEmpty() : base("") { } }
        internal class QueueFull : Exception { public QueueFull() : base("") { } }

        /// <summary>asyncio.run(main()): the compiler passes the coroutine as a function, started on a new event loop.</summary>
        public static T run<T>(Func<Task<T>> main) => PyEventLoop.Run(main);
        public static void run(Func<Task> main) => PyEventLoop.Run(async () => { await main(); return (object?)null; });
        // (an already started task: waited for)
        public static void run(Task t) => t.GetAwaiter().GetResult();
        public static T run<T>(Task<T> t) => t.GetAwaiter().GetResult();

        public static async Task sleep(double seconds)
        {
            if (seconds <= 0) await Task.Yield(); // sleep(0): let the other tasks run
            else await Delay(seconds);
        }

        /// <summary>A delay on the running event loop's clock (ordered by deadline), else a .NET delay.</summary>
        static Task Delay(double seconds) => PyEventLoop.Running is PyEventLoop loop ? loop.Delay(seconds) : Task.Delay(TimeSpan.FromSeconds(Math.Max(0, seconds)));
        public static async Task<T> sleep<T>(double seconds, T result) { await sleep(seconds); return result; }

        /// <summary>await gather(a(), b()): the results in the order given, as a list.</summary>
        public static async Task<List<T>> gather<T>(params Task<T>[] tasks) => (await Task.WhenAll(tasks)).ToList();
        public static async Task<List<T>> gather<T>(params PyTask<T>[] tasks) => (await Task.WhenAll(tasks.Select(t => t.Inner))).ToList();
        /// <summary>gather of tasks with different result types (or none): a list of their results (None for none).</summary>
        public static async Task<List<object?>> gather(params Task[] tasks)
        {
            await Task.WhenAll(tasks);
            return tasks.Select(Builtins.TaskResult).ToList();
        }

        public static PyTask<T> create_task<T>(Task<T> coro, string? name = null) => new PyTask<T>(coro, name);
        public static PyTask create_task(Task coro, string? name = null) => new PyTask(coro, name);
        public static PyTask<T> ensure_future<T>(Task<T> coro) => new PyTask<T>(coro, null);
        public static PyTask ensure_future(Task coro) => new PyTask(coro, null);

        /// <summary>await wait_for(coro, timeout): its result, or TimeoutError when it takes longer.</summary>
        public static async Task<T> wait_for<T>(Task<T> aw, double? timeout)
        {
            if (timeout == null) return await aw;
            var done = await Task.WhenAny(aw, Delay(timeout.Value));
            if (done != aw) throw new TimeoutError();
            return await aw;
        }
        public static Task<T> wait_for<T>(PyTask<T> aw, double? timeout) => wait_for(aw.Inner, timeout);
        public static async Task wait_for(Task aw, double? timeout)
        {
            if (timeout == null) { await aw; return; }
            var done = await Task.WhenAny(aw, Delay(timeout.Value));
            if (done != aw) throw new TimeoutError();
            await aw;
        }

        /// <summary>for t in as_completed(tasks): await t — the tasks' results in the order they finish.</summary>
        public static List<Task<T>> as_completed<T>(IEnumerable<Task<T>> tasks)
        {
            var list = tasks.ToList();
            var buckets = list.Select(_ => new TaskCompletionSource<T>(TaskCreationOptions.RunContinuationsAsynchronously)).ToList();
            int next = -1;
            foreach (var t in list)
                t.ContinueWith(done =>
                {
                    var bucket = buckets[System.Threading.Interlocked.Increment(ref next)];
                    if (done.IsFaulted) bucket.TrySetException(done.Exception!.InnerExceptions);
                    else if (done.IsCanceled) bucket.TrySetCanceled();
                    else bucket.TrySetResult(done.Result);
                }, TaskContinuationOptions.ExecuteSynchronously);
            return buckets.Select(b => b.Task).ToList();
        }

        // the classes (asyncio.Queue() and q: asyncio.Queue): the runtime's types under asyncio's names
        internal sealed class Queue : PyAsyncQueue { public Queue(long maxsize = 0) : base(maxsize) { } }
        internal sealed class Lock : PyAsyncSemaphore { public Lock() : base(1, isLock: true) { } }
        internal sealed class Semaphore : PyAsyncSemaphore { public Semaphore(long value = 1) : base(checked((int)value), isLock: false) { } }
        internal sealed class BoundedSemaphore : PyAsyncSemaphore { public BoundedSemaphore(long value = 1) : base(checked((int)value), isLock: false) { } }
        internal sealed class Event : PyAsyncEvent { }
        internal sealed class TaskGroup : PyTaskGroup { }
    }
